import { useState, useEffect } from "react";
import axios from "axios";

const ImageUpload = () => {
  const [sliderImages, setSliderImages] = useState([]);
  const [bigPhotoImages, setBigPhotoImages] = useState([]);
  const [allPhotos, setAllPhotos] = useState([]);

  const [selectedSlider, setSelectedSlider] = useState([]);
  const [selectedBigPhoto, setSelectedBigPhoto] = useState([]);
  const [selectedAllPhoto, setSelectedAllPhoto] = useState([]);

  useEffect(() => {
    fetchImages();
  }, []);

  const fetchImages = async () => {
    try {
      const response = await axios.get("http://localhost:5000/images");
      setSliderImages(response.data.slider);
      setBigPhotoImages(response.data.bigphoto);
      setAllPhotos(response.data.allphoto);
    } catch (error) {
      console.error("Error fetching images:", error);
    }
  };

  const handleFileChange = (e, type) => {
    const filesArray = Array.from(e.target.files);
    if (type === "slider") setSelectedSlider(filesArray);
    else if (type === "bigphoto") setSelectedBigPhoto(filesArray);
    else if (type === "allphoto") setSelectedAllPhoto(filesArray);
  };

  const handleUpload = async () => {
    const formData = new FormData();

    selectedSlider.forEach((file) => formData.append("slider", file));
    selectedBigPhoto.forEach((file) => formData.append("bigphoto", file));
    selectedAllPhoto.forEach((file) => formData.append("allphoto", file));

    try {
      await axios.post("http://localhost:5000/upload", formData, {
        headers: { "Content-Type": "multipart/form-data" },
      });
      fetchImages(); // Refresh images after upload
    } catch (error) {
      console.error("Error uploading images:", error);
    }
  };

  return (
    <div>
      <h3>Slider Images</h3>
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "slider")} />
      <div>
        {sliderImages.map((img, index) => (
          <img key={index} src={img} alt="Slider" width="100" style={{ margin: "5px" }} />
        ))}
      </div>

      <h3>Big Photos</h3>
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "bigphoto")} />
      <div>
        {bigPhotoImages.map((img, index) => (
          <img key={index} src={img} alt="Big Photo" width="100" style={{ margin: "5px" }} />
        ))}
      </div>

      <h3>All Photos</h3>
      <input type="file" multiple accept="image/*" onChange={(e) => handleFileChange(e, "allphoto")} />
      <div>
        {allPhotos.map((img, index) => (
          <img key={index} src={img} alt="All Photos" width="100" style={{ margin: "5px" }} />
        ))}
      </div>

      <button onClick={handleUpload}>Upload</button>
    </div>
  );
};

export default ImageUpload;
